function mount(root){
const host=document.createElement('section');host.className='pv';root.append(host);let level=-1,done=new Set(),a=digits(345728),selected=0,counts=[],finished=false;const $=s=>host.querySelector(s);
const task=()=>tasks[level],editable=()=>level<0||task().type==='build',exchange=()=>level>=0&&task().type==='exchange';
function select(i){level=i;finished=false;selected=0;const q=task();a=q?digits(q.type==='build'?0:q.n||0):digits(345728);counts=q?.counts?[...q.counts]:[];render();}
function render(){const q=task();host.innerHTML='<div class="pv-hero"><div><div class="pv-kicker">МАТЕМАТИКА · 5 КЛАСС · ЛАБОРАТОРИЯ</div><h2>Город разрядов</h2><p>Одна и та же цифра имеет разное значение в разных разрядах.</p></div><div class="pv-score">⭐ '+done.size+' / '+tasks.length+'</div></div><div class="pv-panel"><div class="pv-row"><button type="button" data-columns>Перейти к сложению и вычитанию</button></div><h3>Мини-теория</h3><div class="pv-theory">Разряд — это место цифры в числе. Справа налево идут единицы, десятки, сотни, тысячи…<br><b>10 единиц = 1 десяток; 10 десятков = 1 сотня; 10 сотен = 1 тысяча.</b><br>Разряды объединяются в классы по три: класс единиц, тысяч, миллионов. Ноль показывает, что в этом разряде ничего нет, но сохраняет место остальных цифр.</div><div class="pv-row"><button type="button" data-level="-1" class="'+(level<0?'active':'')+'">Свободный режим</button>'+tasks.map((t,i)=>'<button type="button" data-level="'+i+'" class="pv-level '+(i===level?'active ':'')+(done.has(i)?'done':'')+'" aria-label="Задание '+(i+1)+'">'+(i+1)+'</button>').join('')+'</div></div><div class="pv-panel"><div class="pv-kicker">'+(q?'ЗАДАНИЕ '+(level+1)+' ИЗ '+tasks.length:'СВОБОДНЫЙ РЕЖИМ')+'</div><div class="pv-task">'+(q?q.text:'Перетаскивай цифры в разные разряды и наблюдай, как меняется число.')+'</div><div class="pv-work"></div><div class="pv-hint" role="status">'+(exchange()?'Нажми «Обменять 10» в нужном разряде.':editable()?'Выбери разряд, затем нажми цифру или перетащи её в ячейку.':'Выбери нужную ячейку в таблице, затем введи ответ.')+'</div><div class="pv-feedback" role="status"></div><form class="pv-row pv-answer">'+(q&&q.type!=='build'?'<label for="pv-ans">Ответ:</label><input id="pv-ans" inputmode="numeric" autocomplete="off" placeholder="Число" aria-label="Ответ">':'')+(q?'<button type="submit" class="primary">Проверить</button>':'')+'<button type="button" data-reset>Сбросить</button>'+(q?'<button type="button" data-next '+(finished?'':'disabled')+'>Следующее →</button>':'')+'</form></div>';
$('[data-columns]').onclick=()=>renderCatalog('math',5,'column-arithmetic');host.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>select(+b.dataset.level));$('[data-reset]').onclick=()=>select(level);if(q){$('[data-next]').onclick=()=>select((level+1)%tasks.length);$('form').onsubmit=e=>{e.preventDefault();check();};}draw();}
function draw(){if(exchange()){drawExchange();return;}const work=$('.pv-work'),previousScroll=work.querySelector('.pv-scroll')?.scrollLeft;work.innerHTML='<div class="pv-scroll"><div class="pv-table"><div class="pv-class">Класс миллионов</div><div class="pv-class">Класс тысяч</div><div class="pv-class">Класс единиц</div>'+[8,7,6,5,4,3,2,1,0].map(i=>'<div class="pv-place '+(selected===i?'active':'')+'" data-place="'+i+'"><div class="pv-label">'+names[i]+'</div><button type="button" class="pv-slot" aria-label="'+names[i]+': '+a[i]+'">'+a[i]+'</button><div class="pv-weight">'+fmt(powers[i])+'</div></div>').join('')+'</div></div>'+(editable()?'<div class="pv-row pv-palette">'+Array.from({length:10},(_,d)=>'<button type="button" draggable="true" data-digit="'+d+'">'+d+'</button>').join('')+'</div>':'')+'<div class="pv-kicker">ЧИСЛО</div><div class="pv-number">'+fmt(num(a))+'</div><div class="pv-expansion">'+(level<0||finished?expansion(a):'')+'</div>';
const scroller=work.querySelector('.pv-scroll');scroller.scrollLeft=previousScroll??scroller.scrollWidth;work.querySelectorAll('[data-place]').forEach(el=>{const i=+el.dataset.place,button=el.querySelector('button');button.onclick=()=>choose(i);button.onkeydown=e=>{if(editable()&&!finished&&/^[0-9]$/.test(e.key)){e.preventDefault();put(i,+e.key);}};el.ondragover=e=>{if(editable()&&!finished){e.preventDefault();el.classList.add('over');}};el.ondragleave=()=>el.classList.remove('over');el.ondrop=e=>{e.preventDefault();el.classList.remove('over');const raw=e.dataTransfer.getData('text/plain');if(editable()&&!finished&&/^[0-9]$/.test(raw))put(i,+raw);};});work.querySelectorAll('[data-digit]').forEach(b=>{b.onclick=()=>put(selected,+b.dataset.digit);b.ondragstart=e=>e.dataTransfer.setData('text/plain',b.dataset.digit);});}
function expansion(a){const v=a.map((d,i)=>d*powers[i]).reverse().filter(Boolean);return v.length?'Разложение: '+v.map(fmt).join(' + ')+' = '+fmt(num(a)):'Разложение: 0';}
function choose(i){selected=i;host.querySelectorAll('[data-place]').forEach(el=>el.classList.toggle('active',+el.dataset.place===i));const q=task();$('.pv-hint').textContent='Выбран разряд: '+names[i].toLowerCase()+'. '+(q&&q.type==='digit'?'Посмотри на цифру в выбранной ячейке.':q&&q.type==='value'?'Умножь цифру на вес выбранного разряда (число под ячейкой).':a[i]+' × '+fmt(powers[i])+' = '+fmt(a[i]*powers[i])+'.');}
function put(i,d){if(!editable()||finished)return;a[i]=d;selected=i;draw();choose(i);}
function drawExchange(flash=-1){$('.pv-work').innerHTML='<div class="pv-exchange">'+[3,2,1,0].map(i=>'<div class="pv-bin '+(flash===i?'flash':'')+'" data-r="'+i+'"><b>'+names[i]+'</b><div class="pv-kicker">'+counts[i]+' шт.'+'</div><div class="pv-tokens">'+Array.from({length:counts[i]},()=>'<span class="pv-token">'+fmt(powers[i])+'</span>').join('')+'</div>'+(i<3?'<button type="button" data-swap="'+i+'" '+(counts[i]<10||finished?'disabled':'')+'>Обменять 10</button>':'')+'</div>').join('')+'</div><div class="pv-expansion">Итого: '+counts.map((n,i)=>n? n+' × '+fmt(powers[i]):null).filter(Boolean).reverse().join(' + ')+'</div>';
host.querySelectorAll('[data-swap]').forEach(b=>b.onclick=()=>{const i=+b.dataset.swap;if(counts[i]<10||finished)return;const before=num(counts);counts[i]-=10;counts[i+1]++;drawExchange(i+1);$('.pv-hint').textContent='10 '+gen[i]+' обменяли на 1 '+['единицу','десяток','сотню','тысячу'][i+1]+'. Общее количество не изменилось: '+fmt(before)+'.';});}
function check(){if(finished)return;const q=task(),input=$('#pv-ans'),raw=input?.value.trim().replace(/\s/g,''),value=input&&/^\d+$/.test(raw)?Number(raw):NaN;let ok=false,solution='',issue='';
if(q.type==='build'){ok=num(a)===q.n;solution='Получилось число '+fmt(q.n)+'. '+expansion(digits(q.n))+'.';issue='Проверь каждую цифру и не забудь нули в пустых разрядах.';}
else if(q.type==='exchange'){const goal=num(q.counts);ok=counts.every(c=>c<10)&&value===goal;solution='Все разряды содержат меньше 10 элементов. Число '+fmt(goal)+'.';issue=counts.some(c=>c>=10)?'В одном из разрядов ещё есть 10 или больше элементов. Сделай обмен.':'Проверь итоговое число.';}
else {const d=digits(q.n)[q.place],expected=q.type==='digit'?d:d*powers[q.place];ok=selected===q.place&&value===expected;solution=q.type==='digit'?'В разряде «'+names[q.place].toLowerCase()+'» стоит цифра '+d+'.':d+' × '+fmt(powers[q.place])+' = '+fmt(expected)+'.';issue=selected!==q.place?'Сначала выбери нужный разряд в таблице.':'Проверь значение цифры: сама цифра и её разрядное значение — не одно и то же.';}
const fb=$('.pv-feedback');fb.className='pv-feedback '+(ok?'good':'bad');if(input){input.className=ok?'good':'bad';input.setAttribute('aria-invalid',String(!ok));}if(ok){finished=true;done.add(level);$('.pv-score').textContent='⭐ '+done.size+' / '+tasks.length;$('[data-level="'+level+'"]').classList.add('done');$('[data-next]').disabled=false;fb.textContent='✓ Верно! '+solution;if(exchange())drawExchange();else draw();}else{fb.textContent='Попробуй ещё раз. '+issue;const work=$('.pv-work');work.classList.remove('pv-shake');void work.offsetWidth;work.classList.add('pv-shake');}}
select(-1);}
