function plan(a,b,op){
 const n=Math.max(String(a).length,String(b).length,String(op==='+'?a+b:a-b).length),arr=x=>Array.from({length:n},(_,j)=>Math.floor(x/10**j)%10),top=arr(a),bottom=arr(b),res=Array(n).fill(null),carry=Array(n).fill(0),steps=[];
 const snap=(type,j,expected,msg,source=null)=>steps.push({type,j,expected,msg,source,top:[...top],bottom:[...bottom],res:[...res],carry:[...carry]});
 for(let j=0;j<n;j++){
 if(op==='−'&&top[j]<bottom[j]){
 let k=j+1;while(k<n&&top[k]===0)k++;
 if(k===n)throw Error('Недопустимое вычитание');
 for(let h=k;h>j;h--){snap('borrow',j,h,'Чтобы помочь разряду «'+names[j]+'», выбери разряд «'+names[h]+'»: отдаём одну единицу и получаем 10 единиц разряда «'+names[h-1]+'».',h);top[h]--;top[h-1]+=10;}
 }
 const sum=op==='+'?top[j]+bottom[j]+carry[j]:top[j]-bottom[j],digit=sum%10;
 snap('digit',j,digit,(op==='+'?top[j]+' + '+bottom[j]+(carry[j]?' + '+carry[j]:''):top[j]+' − '+bottom[j])+' = '+sum+'. '+(op==='+'&&sum>=10?'Пишем '+digit+', а одну единицу переносим в соседний старший разряд.':'Записываем '+digit+' в текущий разряд.'));
 res[j]=digit;
 if(op==='+'&&sum>=10){snap('carry',j,j+1,'Десять единиц разряда «'+names[j]+'» превращаются в одну единицу разряда «'+names[j+1]+'». Нажми на следующий разряд.',j+1);carry[j+1]=1;}
 }
 snap('done',n-1,null,'Готово! Проверь вычисление обратным действием.');
 return steps;
}
