function division(n,d){const ds=String(n).split('').map(Number);let first=0,p=ds[0];while(p<d&&first<ds.length-1)p=p*10+ds[++first];const rows=[];let r=0;for(let i=first;i<ds.length;i++){const x=i===first?p:r*10+ds[i],q=Math.floor(x/d),product=q*d;r=x-product;rows.push({i,x,q,product,r,place:places[ds.length-1-i],next:ds[i+1]});}return {ds,first,rows,quotient:rows.reduce((v,t)=>v*10+t.q,0),remainder:r};}
